// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/investigations", wrapper.CreateInvestigation)
	router.GET(options.BaseURL+"/investigations/:investigation_id", wrapper.GetInvestigation)
	router.GET(options.BaseURL+"/investigations/:investigation_id/status", wrapper.GetInvestigationStatus)
	router.POST(options.BaseURL+"/investigations/:investigation_id/cancel", wrapper.CancelInvestigation)
	router.GET(options.BaseURL+"/sources", wrapper.ListSources)
	router.GET(options.BaseURL+"/investigations/:investigation_id/reviews", wrapper.ListInvestigationReviews)
	router.GET(options.BaseURL+"/reviews/:review_id", wrapper.GetReview)
	router.POST(options.BaseURL+"/reviews/:review_id/decision", wrapper.DecideReview)
	router.POST(options.BaseURL+"/reviews/:review_id/decision/revert", wrapper.RevertReviewDecision)
	router.GET(options.BaseURL+"/investigations/:investigation_id/entities", wrapper.ListInvestigationEntities)
	router.GET(options.BaseURL+"/entities/:entity_id", wrapper.GetEntity)
	router.POST(options.BaseURL+"/entities/:entity_id/expand", wrapper.ExpandEntity)
	router.GET(options.BaseURL+"/investigations/:investigation_id/graph", wrapper.GetInvestigationGraph)
	router.GET(options.BaseURL+"/investigations/:investigation_id/timeline", wrapper.GetInvestigationTimeline)
	router.GET(options.BaseURL+"/relationships/:relationship_id", wrapper.GetRelationship)
	router.GET(options.BaseURL+"/claims/:claim_id/evidence", wrapper.GetClaimEvidence)
	router.GET(options.BaseURL+"/artifacts/:artifact_id/content", wrapper.GetArtifactContent)
}
